import{_ as e,o as r,c as a,a5 as n}from"./chunks/framework.CslsFoWx.js";const p=JSON.parse('{"title":"Étude commerciale — vendre Vendora : prix, canaux et positionnement (Tunisie, France)","description":"","frontmatter":{},"headers":[],"relativePath":"commercial/etude-commerciale.md","filePath":"generated/commercial/etude-commerciale.md","lastUpdated":null}'),s={name:"commercial/etude-commerciale.md"};function i(o,t,d,l,u,c){return r(),a("div",null,[...t[0]||(t[0]=[n('<div><h1 id="etude-commerciale-—-vendre-vendora-prix-canaux-et-positionnement-tunisie-france" tabindex="-1">Étude commerciale — vendre Vendora : prix, canaux et positionnement (Tunisie, France) <a class="header-anchor" href="#etude-commerciale-—-vendre-vendora-prix-canaux-et-positionnement-tunisie-france" aria-label="Permalink to &quot;Étude commerciale — vendre Vendora : prix, canaux et positionnement (Tunisie, France)&quot;">​</a></h1><blockquote><p>Date : 05/11/2026 · Statut : <strong>étude</strong> (recommandations à arbitrer, rien n&#39;est décidé) · Auteur : équipe Vendora</p><p>Complète, sans la remplacer, l&#39;<a href="/VendoraSystem-docs/commercial/etude-concurrentielle">étude concurrentielle du 25/10/2026</a> (benchmark de 17 acteurs, réglementation, vérification contradictoire) et le <a href="/VendoraSystem-docs/commercial/actions-terrain">plan d&#39;actions terrain du 28/10/2026</a>. Les faits déjà sourcés là-bas sont repris avec la mention « (étude concurrentielle) » ; les nouvelles vérifications sont datées du 05/11/2026.</p><p>Conventions : <strong>[Officiel]</strong> source légale ou institutionnelle · <strong>[Vendeur]</strong> page de l&#39;éditeur · <strong>[Tiers]</strong> presse, comparateur · <strong>[Estimation]</strong> calcul ou hypothèse de l&#39;équipe, à valider sur le terrain · <strong>[Non vérifié]</strong> recherché sans succès le 05/11/2026.</p></blockquote><hr><h2 id="_1-resume-executif" tabindex="-1">1. Résumé exécutif <a class="header-anchor" href="#_1-resume-executif" aria-label="Permalink to &quot;1. Résumé exécutif&quot;">​</a></h2><ol><li><strong>Tunisie — positionnement</strong> : « La caisse qui ne lâche jamais en plein rush, en arabe et en français, pour l&#39;épicerie comme pour le café, au prix du marché local, et bientôt homologuée. » On commence par le <strong>commerce de détail</strong> (non soumis à NACEF), on ouvre la restauration dès l&#39;homologation.</li><li><strong>France — positionnement</strong> : « La caisse sans commission ni engagement, sur Android comme sur iPhone, qui continue sans internet et vous met en règle pour l&#39;e-reporting 2027. » Cible : les indépendants mal servis par les solutions iPad sur devis ou les offres « gratuites + commission ».</li><li><strong>Prix recommandés en Tunisie (en dinars, facturés sur place)</strong> : Essentiel <strong>39 DT</strong>, Commerce <strong>69 DT</strong>, Restaurant <strong>99 DT</strong> HT/mois, appareil supplémentaire <strong>15 DT</strong>. La grille actuelle convertie (29 € ≈ 99 DT) coûte <strong>3 à 4 fois</strong> le prix d&#39;ancrage (Kesti 29 DT, Al-Makhzan 79 DT) : elle ne se vendra pas.</li><li><strong>Prix recommandés en France</strong> : on garde <strong>29 / 49 / 79 € HT</strong> et 9 € par appareil, plus une <strong>offre fondateurs</strong> (−30 % pendant 12 mois pour les 30 premiers commerces), l&#39;<strong>e-reporting inclus</strong> dans Commerce et Restaurant, et une hausse de Restaurant à 89 € seulement après la certification NF525.</li><li><strong>État honnête</strong> : le produit est avancé (phases 0 à 3 faites, 1 815 tests), mais il n&#39;y a <strong>ni société, ni hébergement de production, ni certification NF525, ni homologation NACEF, ni client de référence</strong>. Aucun de ces points ne relève du code.</li><li><strong>Action prioritaire 1</strong> : créer la société éditrice (et décider où elle facture), puis l&#39;hébergement de production — c&#39;est le prérequis de tout (attestation NF525, factures, contrats PA et paiements, nom de domaine professionnel).</li><li><strong>Action prioritaire 2</strong> : un <strong>programme pilote de 10 commerces</strong> (6 en Tunisie, 4 en France) gratuit 3 mois contre témoignage et captures, pour obtenir les premières références avant toute dépense marketing.</li><li><strong>Action prioritaire 3</strong> : débloquer la conformité — cahier des charges NACEF depuis la Tunisie, contrat avec une plateforme agréée (avant fin T1 2027), dossier de certification NF525 lancé au T2 2027.</li><li><strong>Objectif à 12 mois (scénario de base)</strong> : 110 clients payants (70 TN, 40 FR), environ <strong>3 700 € de revenu mensuel récurrent</strong> (~3 200 € après remises fondateurs), churn mensuel &lt; 3 % ; le scénario haut atteint 240 clients et ~8 000 €.</li><li><strong>Canal principal</strong> : en Tunisie, des <strong>revendeurs installateurs de matériel</strong> commissionnés ; en France, les <strong>experts-comptables</strong> et revendeurs régionaux, appuyés par la page de démo et l&#39;essai de 14 jours.</li></ol><hr><h2 id="_2-marches" tabindex="-1">2. Marchés <a class="header-anchor" href="#_2-marches" aria-label="Permalink to &quot;2. Marchés&quot;">​</a></h2><h3 id="_2-1-tunisie" tabindex="-1">2.1 Tunisie <a class="header-anchor" href="#_2-1-tunisie" aria-label="Permalink to &quot;2.1 Tunisie&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Indicateur</th><th>Valeur</th><th>Source</th><th>Fiabilité</th></tr></thead><tbody><tr><td>Petits commerces et épiceries de proximité</td><td>~290 000</td><td><a href="https://www.tunisienumerique.com/les-grandes-surfaces-tunisiennes-entre-resistance-et-revolution-du-commerce-en-ligne/" target="_blank" rel="noreferrer">Tunisie Numérique</a> (consulté le 05/11/2026, article sans date visible)</td><td>[Tiers], non attribué à l&#39;INS</td></tr><tr><td>Petits commerçants (ministère du Commerce)</td><td>~242 000 en 2015 → ~293 000</td><td><a href="https://africanmanager.com/commerce-de-detail-bataille-rangee-entre-petits-et-grands/" target="_blank" rel="noreferrer">African Manager</a> (consulté le 05/11/2026)</td><td>[Tiers] citant le ministère</td></tr><tr><td>Entreprises du commerce de détail (hors automobile)</td><td>240 026 fin 2020</td><td><a href="https://managers.tn/2021/11/03/la-tunisie-compte-801-453-entreprises-fin-2020" target="_blank" rel="noreferrer">Managers</a> citant l&#39;INS</td><td>[Tiers] citant l&#39;INS</td></tr><tr><td>Cafés</td><td>« plus de 20 000 », ~120 000 emplois (déclaration de la Chambre nationale des cafés, 2020)</td><td>recherche du 05/11/2026, sans chiffre récent</td><td>[Tiers], ancien</td></tr><tr><td>Établissements visés par NACEF</td><td><strong>non publié</strong></td><td>recherché le 05/11/2026 (DGI, presse)</td><td>[Non vérifié]</td></tr><tr><td>Euro / dinar</td><td>1 € = 3,3749 DT (02/10/2026, cours BCT)</td><td><a href="https://www.tuniscope.com/article/441523/business/economie/taux-de-change-en-tunisie-l-euro-a-3-3749-dinars-le-dollar-a-2-9775-dinars-351411" target="_blank" rel="noreferrer">Tuniscope</a></td><td>[Tiers] citant la BCT</td></tr></tbody></table><p><strong>Structure [Estimation]</strong> : un commerce traditionnel très atomisé (échoppes familiales, une caisse au plus), une grande distribution concentrée équipée par des intégrateurs, une restauration de quartier (cafés, snacks, salons de thé, pâtisseries) en forte densité urbaine. Le marché adressable de Vendora la première année, c&#39;est le haut de ce tissu : supérettes, épiceries fines, boutiques, cafés et restaurants de 3 à 15 salariés du Grand Tunis, de Sousse et de Sfax — de l&#39;ordre de <strong>quelques dizaines de milliers d&#39;établissements</strong> [Estimation, à affiner avec l&#39;INS ou le registre national des entreprises].</p><p><strong>Équipement actuel [Estimation, entretiens terrain à mener]</strong> : cahier et calculatrice dans le petit commerce ; caisses enregistreuses autonomes ou logiciels Windows à licence (type Wasel, 199-599 DT, étude concurrentielle) ; tablette Android avec un SaaS local à 29-79 DT/mois chez les cafés modernes (Kesti, Al-Makhzan). Le smartphone Android est l&#39;outil universel du commerçant ; l&#39;iPhone est minoritaire mais présent chez les gérants de franchises.</p><p><strong>Réglementation qui pousse à s&#39;équiper</strong> (détail dans l&#39;étude concurrentielle §2.1 et dans la <a href="/VendoraSystem-docs/specs/15-fiscal-compliance">spec 15</a>) :</p><table tabindex="0"><thead><tr><th>Date</th><th>Assujettis à la caisse homologuée NACEF</th><th>Conséquence commerciale</th></tr></thead><tbody><tr><td>01/11/2025</td><td>Restaurants touristiques classés, salons de thé, cafés de 2e et 3e catégorie</td><td>Déjà équipés ou en retard : vendre du remplacement</td></tr><tr><td><strong>01/07/2026</strong></td><td>Autres <strong>personnes morales</strong> de la consommation sur place</td><td>En vigueur : demande actuelle, nous ne pouvons pas encore y répondre</td></tr><tr><td>01/07/2027</td><td>Personnes physiques au régime réel</td><td><strong>La vague que nous pouvons viser</strong> si l&#39;homologation arrive avant le T2 2027</td></tr><tr><td>01/07/2028</td><td>Autres personnes physiques</td><td>Généralisation, volume maximal</td></tr></tbody></table><p>Sources : arrêté du 14/10/2025, confirmé par <a href="https://www.webmanagercenter.com/2026/05/21/567214/lutte-contre-levasion-fiscale-la-tunisie-accelere-la-generalisation-des-caisses-enregistreuses/" target="_blank" rel="noreferrer">Webmanagercenter, 21/05/2026</a> <strong>[Tiers]</strong>. La presse indique que les logiciels déjà en place pourront continuer <strong>s&#39;ils sont homologués</strong>, et que la DGI a rappelé le 08/04/2026 aux établissements de la première phase de se rapprocher d&#39;un <strong>fournisseur homologué</strong> (liste sur jibaya.tn, géo-bloquée hors Tunisie). <strong>Point clé</strong> : l&#39;obligation porte sur la <strong>consommation sur place</strong> — le commerce de détail (épicerie, boutique, supérette) n&#39;est pas concerné, ce qui nous permet de vendre dès maintenant à ce segment.</p><p><strong>Paiements</strong> : espèces dominantes, bancarisation ~38 %, ardoise (« karna ») courante, Flouci 1,3 % HT, Konnect, Paymee, D17 sans API publique, label TUNPAY annoncé en 05/2026 (étude concurrentielle §2.3). Vendora a déjà les connecteurs simulés par magasin ; les passerelles réelles attendent les comptes marchands.</p><h3 id="_2-2-france" tabindex="-1">2.2 France <a class="header-anchor" href="#_2-2-france" aria-label="Permalink to &quot;2.2 France&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Indicateur</th><th>Valeur</th><th>Source</th><th>Fiabilité</th></tr></thead><tbody><tr><td>Entreprises de restauration (NAF 561 + 562)</td><td>&gt; 179 000 (juin 2024)</td><td><a href="https://tool-advisor.fr/blog/chiffres-statistiques-restauration/" target="_blank" rel="noreferrer">Tool-advisor</a> citant l&#39;Insee (consulté le 05/11/2026)</td><td>[Tiers] citant l&#39;Insee</td></tr><tr><td>Restauration rapide</td><td>~50 000 établissements en 2025</td><td><a href="https://copeps.fr/actualites/insee-restauration-rapide/" target="_blank" rel="noreferrer">Copeps</a> citant l&#39;Insee</td><td>[Tiers]</td></tr><tr><td>Épiceries et supérettes</td><td>8 % du marché alimentaire, 24 Md€ en 2024</td><td><a href="https://www.xerfi.com/presentationetude/le-marche-des-epiceries-et-superettes_DIS06" target="_blank" rel="noreferrer">Xerfi</a> (présentation d&#39;étude)</td><td>[Tiers]</td></tr><tr><td>Commerces alimentaires spécialisés</td><td>102 pour 100 000 habitants (France métropolitaine)</td><td><a href="https://www.insee.fr/fr/statistiques/fichier/version-html/6524099/lm_cp_2022_ina_120.pdf" target="_blank" rel="noreferrer">Insee, 2022</a></td><td>[Officiel], soit ~68 000 [Estimation]</td></tr><tr><td>Paiements en magasin</td><td>carte 48 %, espèces 43 %, mobile 4 % (2024)</td><td><a href="https://www.banque-france.fr/fr/publications-et-statistiques/publications/les-francais-continuent-dapprecier-les-especes-meme-si-leur-usage-se-reduit-au-profit-des-paiements" target="_blank" rel="noreferrer">Banque de France, bulletin 02/2025</a></td><td>[Officiel]</td></tr><tr><td>Experts-comptables inscrits</td><td>21 611 (19 490 cabinets)</td><td><a href="https://les-experts-comptables.fr/ressources/nombre-experts-comptables-france" target="_blank" rel="noreferrer">les-experts-comptables.fr</a> citant le CNOEC (date de référence incertaine : 2023 ou 2025)</td><td>[Tiers]</td></tr></tbody></table><p><strong>Équipement actuel [Estimation]</strong> : quasiment tous les commerces encaissant des particuliers ont une caisse depuis l&#39;obligation de 2018 (art. 286 CGI). Le marché français est donc un <strong>marché de remplacement</strong> : on gagne un client quand son engagement de 36-48 mois se termine, quand son iPad vieillit, quand sa solution « gratuite » lui coûte trop en commissions, ou quand une obligation nouvelle l&#39;oblige à changer.</p><p><strong>Réglementation qui pousse à changer</strong> :</p><table tabindex="0"><thead><tr><th>Obligation</th><th>Date</th><th>Effet commercial</th></tr></thead><tbody><tr><td>Art. 286 CGI — inaltérabilité, sécurisation, conservation, archivage ; attestation éditeur <strong>rétablie</strong> par la LF2026, certification NF525 / LNE en option</td><td>En vigueur</td><td>Amende de 7 500 € par logiciel non justifié : la preuve de conformité est un critère d&#39;achat (étude concurrentielle §3.1)</td></tr><tr><td>Réception des factures électroniques</td><td>Depuis le 01/09/2026, toutes les entreprises</td><td>Les commerçants découvrent les plateformes agréées : moment pédagogique</td></tr><tr><td><strong>E-reporting B2C</strong> et émission e-facture pour les <strong>PME et micro</strong></td><td><strong>01/09/2027</strong></td><td>Argument « mise en règle incluse » à partir du T2 2027 ; 500 € par transmission manquante (plafond 45 000 €/an)</td></tr><tr><td>Titres-restaurant dématérialisés, 7j/7</td><td>Réforme non votée (texte au Sénat)</td><td>Vendora gère déjà le titre et le paiement scindé (lot 3.13)</td></tr><tr><td>Recodification du CGI</td><td>01/01/2027</td><td>Mettre à jour les références sur l&#39;attestation et la page publique</td></tr></tbody></table><p><strong>Paiements</strong> : carte majoritaire depuis 2024, espèces encore à 43 %, titres-restaurant incontournables en restauration et en alimentaire, pourboires défiscalisés jusqu&#39;au 31/12/2028 (étude concurrentielle §3.1). Le TPE reste au commerçant (banque ou PSP) ; Vendora ne prend <strong>aucune commission</strong>.</p><hr><h2 id="_3-concurrence-et-prix" tabindex="-1">3. Concurrence et prix <a class="header-anchor" href="#_3-concurrence-et-prix" aria-label="Permalink to &quot;3. Concurrence et prix&quot;">​</a></h2><h3 id="_3-1-tunisie" tabindex="-1">3.1 Tunisie <a class="header-anchor" href="#_3-1-tunisie" aria-label="Permalink to &quot;3.1 Tunisie&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Acteur</th><th>Modèle et prix public</th><th>Matériel</th><th>Engagement</th><th>NACEF affiché</th><th>Forces face à nous</th><th>Faiblesses face à nous</th></tr></thead><tbody><tr><td><strong>Kesti</strong></td><td>SaaS <strong>29 DT/mois</strong>, annuel « 2 mois offerts », essai 1 mois sans CB</td><td>Tablette Android ≥ 8″ obligatoire (« le téléphone seul ne suffit pas »), imprimantes ESC/POS</td><td>Aucun</td><td>Non mentionné</td><td>Prix très bas, local, F&amp;B</td><td>Mono-vertical F&amp;B, pas d&#39;iOS annoncé, offline non documenté</td></tr><tr><td><strong>Al-Makhzan</strong></td><td><strong>79 TND/mois</strong> Pro, remises trimestrielle (−18 TND) et annuelle (−2 mois), garantie 30 jours</td><td>Non précisé</td><td>Sans engagement</td><td>Non mentionné</td><td>KDS, menu QR et commande en ligne, food-cost, scan des factures, installation et migration incluses, support 24/7</td><td>Restaurant seul ; pas de commerce de détail, pas d&#39;ardoise annoncée</td></tr><tr><td><strong>Wasel</strong></td><td>Licence définitive <strong>199 DT</strong> (lancement, « jusqu&#39;au 7 novembre »), <strong>599 DT</strong> prix normal, installation incluse</td><td>PC Windows</td><td>Aucun (achat)</td><td>Non mentionné</td><td>Paiement unique (culture locale), karna native, 100 % local</td><td>Mono-poste Windows, pas de cloud ni mobile ni multi-magasins</td></tr><tr><td><strong>Odoo POS</strong> (intégrateurs : Shazler IT…)</td><td>Licence en dollars par utilisateur (~24,90 $ promo selon un article algérien d&#39;août 2026) + intégration sur devis</td><td>PC ou tablette</td><td>Contrat d&#39;intégrateur</td><td>Non vérifié</td><td>ERP complet, comptabilité, réseau d&#39;intégrateurs</td><td>Projet long, localisation tunisienne inégale, coût total élevé</td></tr><tr><td><strong>Zoho (Zakya)</strong></td><td>Lancé en Inde (₹649/mois) ; <strong>aucune offre Maghreb trouvée</strong></td><td>—</td><td>—</td><td>—</td><td>Marque, écosystème Zoho</td><td>Absent du marché à date</td></tr><tr><td><strong>ASM POS, KAISSE</strong></td><td>Prix non publiés</td><td>Matériel fiscal</td><td>?</td><td><strong>Auto-déclarés conformes</strong> (non vérifié sur jibaya.tn)</td><td>Seuls à afficher la conformité</td><td>Positionnement matériel, peu de mobile</td></tr></tbody></table><p>Sources (consultées le 05/11/2026) : <a href="https://kesti.tn/" target="_blank" rel="noreferrer">kesti.tn</a>, <a href="https://al-makhzan.com/" target="_blank" rel="noreferrer">al-makhzan.com</a>, <a href="https://wasel.tn/desktop/fnb" target="_blank" rel="noreferrer">wasel.tn</a> <strong>[Vendeur]</strong> ; <a href="https://www.erpresearch.com/odoo-partners/shazler-it" target="_blank" rel="noreferrer">ERPResearch — Shazler IT</a>, <a href="https://zoomalgerie.com/odoo-algerie-prix-integrateurs/" target="_blank" rel="noreferrer">ZoomAlgérie</a> <strong>[Tiers]</strong> ; <a href="https://www.dinamalar.com/news/kalvimalar-news-en/zoho-launches-zakya-to-offer-retail-pos-solution/50280" target="_blank" rel="noreferrer">Dinamalar</a> <strong>[Tiers]</strong> ; ASM / KAISSE : étude concurrentielle §2.1.</p><p><strong>Lecture</strong> : le marché tunisien se paie entre <strong>29 et 79 DT par mois</strong> ou en <strong>licence unique de 200 à 600 DT</strong>. Aucun acteur grand public n&#39;affiche l&#39;homologation NACEF sur sa page : le premier qui la décroche et la montre aura un argument décisif pour les vagues 2027 et 2028.</p><h3 id="_3-2-france" tabindex="-1">3.2 France <a class="header-anchor" href="#_3-2-france" aria-label="Permalink to &quot;3.2 France&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Acteur</th><th>Prix public (HT)</th><th>Commission carte</th><th>Matériel</th><th>Engagement</th><th>Forces face à nous</th><th>Faiblesses face à nous</th></tr></thead><tbody><tr><td><strong>SumUp</strong></td><td>0 €/mois ; <strong>Caisse Plus 49 €</strong> ; POS Pro ~79 € (tiers)</td><td>1,75 % ou 0,89 % avec Paiements Plus</td><td>Kits <strong>549-649 €</strong> (caisse, imprimante, tiroir, douchette)</td><td>Non</td><td>Marque, matériel clé en main, NF525 AFNOR</td><td>Modèle à la commission, offline limité, matériel propriétaire</td></tr><tr><td><strong>Square</strong></td><td>0 € ; <strong>Restaurants 59 €/mois par point de vente</strong> (appareils illimités) ; KDS 15 €/mois hors abonnement</td><td><strong>1,65 %</strong> en magasin</td><td>Matériel Square</td><td>Non</td><td>Gratuit pour démarrer, appareils illimités</td><td>Auto-attestation NF525, offline limité aux paiements</td></tr><tr><td><strong>Zettle (PayPal)</strong></td><td>0 €/mois</td><td>1,75 % (tiers)</td><td>Lecteur ~19-79 € (promo, tiers)</td><td>Non</td><td>Simplicité, PayPal</td><td>Pas de vrai mode hors ligne, peu de gestion</td></tr><tr><td><strong>Lightspeed Restaurant</strong></td><td><strong>89 / 159 / 249 €/mois</strong></td><td>Paiements Lightspeed</td><td>iPad</td><td>Variable</td><td>Profondeur restaurant, multi-établissements, INFOCERT</td><td>iPad seul, cher pour un indépendant</td></tr><tr><td><strong>Tactill</strong></td><td><strong>39 €/mois</strong> (≈ 29 € en annuel) ; Tactill Box 1 189 € (iPad + imprimante-tiroir + 1 an)</td><td>1,4 % + 0,25 € (étude concurrentielle)</td><td>iPad</td><td>Non</td><td>Commerce de détail, simplicité</td><td>iOS seul, caisse supplémentaire payante</td></tr><tr><td><strong>Hiboutik</strong></td><td>Version <strong>gratuite</strong> ; premium 9,90 à 16,90 €/mois selon les sources</td><td>Non</td><td>Navigateur, tout matériel</td><td>Non</td><td>Gratuit, web</td><td>Pas d&#39;app native hors ligne, support limité</td></tr><tr><td><strong>L&#39;Addition</strong></td><td>« Dès 49 €/mois » (étude du 25/10) ; <strong>la page prix ne publie plus que des devis</strong> (05/11)</td><td>L&#39;Addition Pay+</td><td>iPad, iPhone</td><td>Leasing 36-48 mois selon tiers</td><td>Offline par routeur local, CHR</td><td>Apple seul, devis, engagement</td></tr><tr><td><strong>Zelty</strong></td><td>~89 €/mois + modules 19-60 € (tiers ; devis)</td><td>Non</td><td>iPad</td><td>Devis</td><td>Multisite restauration, ~4 000 restaurants</td><td>Opacité, avis support mitigés</td></tr><tr><td><strong>Innovorder</strong></td><td><strong>79 € / 299 €/mois</strong> ; bornes 2 000-15 000 €</td><td>Non</td><td>Android propriétaire</td><td>Devis</td><td>Bornes, franchises, marque blanche commande en ligne</td><td>Premium, peu adapté aux petits</td></tr><tr><td><strong>Clyo Systems</strong></td><td>« À partir de 49 € » (Capterra, nature du prix non précisée) ; devis</td><td>?</td><td>PC, tablette, caisse de marque</td><td>?</td><td>Commerce de détail, NF525</td><td>Positionnement matériel et revendeurs, interface ancienne [Estimation]</td></tr></tbody></table><p>Sources (consultées le 05/11/2026 sauf mention) : <a href="https://www.sumup.com/fr-fr/caisse-enregistreuse/" target="_blank" rel="noreferrer">sumup.com</a>, <a href="https://squareup.com/fr/fr/pricing" target="_blank" rel="noreferrer">squareup.com</a>, <a href="https://www.laddition.com/fr/prix-logiciel-caisse" target="_blank" rel="noreferrer">laddition.com</a> <strong>[Vendeur]</strong> ; Zettle : <a href="https://independant.io/avis/izettle/" target="_blank" rel="noreferrer">independant.io</a>, <a href="https://www.comparateurbanque.com/izettle/izettle-les-frais/" target="_blank" rel="noreferrer">comparateurbanque.com</a> <strong>[Tiers]</strong> ; Tactill : <a href="https://tool-advisor.fr/logiciel-de-caisse/comparatif/tactill/" target="_blank" rel="noreferrer">tool-advisor.fr</a>, <a href="https://independant.io/avis/tactill/" target="_blank" rel="noreferrer">independant.io</a> <strong>[Tiers]</strong> ; Hiboutik : <a href="https://independant.io/avis/hiboutik/" target="_blank" rel="noreferrer">independant.io</a>, <a href="https://www.capterra.fr/software/129660/hiboutik" target="_blank" rel="noreferrer">capterra.fr</a> <strong>[Tiers]</strong> ; Clyo : <a href="https://www.capterra.fr/software/195733/clyo-systems" target="_blank" rel="noreferrer">capterra.fr</a> <strong>[Tiers]</strong> ; Lightspeed, Zelty, Innovorder : étude concurrentielle du 25/10/2026.</p><p><strong>Lecture</strong> : trois étages de prix en France — <strong>0 € + commission</strong> (SumUp, Square, Zettle, Hiboutik gratuit), <strong>29-59 €</strong> pour le commerce (Tactill, SumUp Plus, Square Restaurants), <strong>79-249 €</strong> pour la restauration spécialisée, souvent sur devis et sur iPad. Vendora à 29 / 49 / 79 € sans commission se place au <strong>bas du deuxième étage avec la profondeur du troisième</strong> (salle, cuisine, food-cost, multi-magasins, FEC).</p><h3 id="_3-3-ce-que-les-concurrents-ont-et-pas-nous-a-date" tabindex="-1">3.3 Ce que les concurrents ont et pas nous (à date) <a class="header-anchor" href="#_3-3-ce-que-les-concurrents-ont-et-pas-nous-a-date" aria-label="Permalink to &quot;3.3 Ce que les concurrents ont et pas nous (à date)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Écart</th><th>Qui l&#39;a</th><th>Impact commercial</th><th>Réponse</th></tr></thead><tbody><tr><td>Homologation NACEF / certification NF525 affichée</td><td>ASM, KAISSE (auto-déclarés) ; SumUp, Lightspeed, Innovorder, Clyo</td><td>Bloquant en restauration tunisienne, fort en France</td><td>§9, prérequis</td></tr><tr><td>Matériel vendu clé en main</td><td>SumUp, Tactill, L&#39;Addition</td><td>Le commerçant veut un seul interlocuteur</td><td>Packs avec un revendeur partenaire (§6.4)</td></tr><tr><td>Menu QR et commande en ligne</td><td>Al-Makhzan, L&#39;Addition, Innovorder</td><td>Visible en démo restaurant</td><td>Phase 4 (spec 16)</td></tr><tr><td>Vente au poids sur balance connectée, variantes taille × couleur</td><td>Retail généralistes</td><td>Épicerie vrac, boutiques de vêtements</td><td>Phase 4 ; les étiquettes de balance (EAN 21/24) sont déjà lues</td></tr><tr><td>Paiement intégré au TPE</td><td>SumUp, Square, Zettle</td><td>Moins de double saisie</td><td>Connecteur TPE simulé ; intégration réelle via PSP (phase 4)</td></tr><tr><td>Support téléphonique 7j/7</td><td>Al-Makhzan (24/7), grands acteurs</td><td>Rassurant pour un premier achat</td><td>Support WhatsApp et email aux heures d&#39;ouverture (§7.3)</td></tr></tbody></table><hr><h2 id="_4-notre-positionnement" tabindex="-1">4. Notre positionnement <a class="header-anchor" href="#_4-notre-positionnement" aria-label="Permalink to &quot;4. Notre positionnement&quot;">​</a></h2><h3 id="_4-1-proposition-de-valeur" tabindex="-1">4.1 Proposition de valeur <a class="header-anchor" href="#_4-1-proposition-de-valeur" aria-label="Permalink to &quot;4.1 Proposition de valeur&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Promesse</th><th>Preuve disponible aujourd&#39;hui</th><th>Pour qui c&#39;est décisif</th></tr></thead><tbody><tr><td><strong>Hors ligne réel, multi-appareils</strong> : caisse, téléphones de salle et cuisine continuent de se parler sans internet (hub local)</td><td>Démontré sur émulateur et simulateur ; page de démo de 106 écrans</td><td>Cafés et restaurants en zone de coupures (TN), restaurants en sous-sol ou centre ancien (FR)</td></tr><tr><td><strong>Android ET iOS</strong>, téléphone et tablette</td><td>Deux apps natives au même niveau</td><td>Le commerçant garde son matériel ; pas d&#39;iPad imposé (FR), Android majoritaire (TN)</td></tr><tr><td><strong>Commerce et restaurant</strong> dans un seul produit</td><td>Formules Commerce et Restaurant, mêmes écrans</td><td>Commerçants mixtes (café-épicerie, boulangerie-snack, traiteur)</td></tr><tr><td><strong>Français, anglais, arabe</strong> avec miroir complet</td><td>Caisses, back-office et console traduits</td><td>Tunisie (personnel arabophone), France (équipes multilingues)</td></tr><tr><td><strong>Rien ne se perd</strong> : ventes scellées, Z chaîné, alertes anti-fraude</td><td>Livré (lots 1.x et 3.9)</td><td>Propriétaire absent, franchise</td></tr><tr><td><strong>Prix public, sans engagement, sans commission</strong></td><td>Grille sur la page publique, lue dans la console</td><td>France surtout</td></tr><tr><td><strong>Gestion complète</strong> : stock, fournisseurs, inventaires, fidélité, ardoise, multi-magasins, exports comptables et FEC</td><td>Livré (phase 3)</td><td>Épiceries fines, petites chaînes</td></tr></tbody></table><h3 id="_4-2-swot-—-tunisie" tabindex="-1">4.2 SWOT — Tunisie <a class="header-anchor" href="#_4-2-swot-—-tunisie" aria-label="Permalink to &quot;4.2 SWOT — Tunisie&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Forces</th><th>Faiblesses</th></tr></thead><tbody><tr><td>Hors ligne multi-appareils (aucun local ne le documente) · arabe avec RTL · ardoise tracée · commerce + restaurant · anti-fraude pour le propriétaire absent · connecteurs Flouci / Konnect / Paymee prêts côté code</td><td><strong>Pas d&#39;homologation NACEF</strong> (cahier des charges inaccessible) · prix actuel en euros hors marché · facturation en euros depuis l&#39;étranger · aucune présence physique ni référence · pas de menu QR</td></tr><tr><td><strong>Opportunités</strong></td><td><strong>Menaces</strong></td></tr><tr><td>Vagues NACEF 2027 et 2028 (personnes physiques) · retards de déploiement constatés · commerce de détail non couvert par les SaaS locaux · TUNPAY (QR unique) · franchises locales en croissance</td><td>Kesti à 29 DT tire les prix vers le bas · un concurrent local homologué avant nous · licence unique (Wasel) préférée par une partie du marché · contrôle des changes · délais d&#39;homologation inconnus</td></tr></tbody></table><h3 id="_4-3-swot-—-france" tabindex="-1">4.3 SWOT — France <a class="header-anchor" href="#_4-3-swot-—-france" aria-label="Permalink to &quot;4.3 SWOT — France&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Forces</th><th>Faiblesses</th></tr></thead><tbody><tr><td>Android + iOS face à l&#39;iPad-only · offline réel · grille publique sans engagement ni commission · titres-restaurant, pourboires, food-cost, FEC, e-reporting déjà codés · multi-magasins inclus dans Sur mesure</td><td><strong>Pas de certification NF525</strong> (attestation possible seulement une fois la société créée) · plateforme agréée simulée · inconnu, sans avis clients · pas de matériel vendu · pas de paiement TPE intégré · fondateur seul et à distance du terrain</td></tr><tr><td><strong>Opportunités</strong></td><td><strong>Menaces</strong></td></tr><tr><td>E-reporting PME au 01/09/2027 · fins d&#39;engagements de 36-48 mois · lassitude des commissions · experts-comptables cherchant des caisses qui exportent proprement · réforme des titres-restaurant</td><td>Offres gratuites financées par la commission · acteurs installés qui ajouteront l&#39;e-reporting · nouveau revirement législatif sur NF525 · coût d&#39;acquisition élevé en ligne (mots-clés « logiciel de caisse »)</td></tr></tbody></table><h3 id="_4-4-etat-actuel-honnete-et-positionnement-cible-a-12-mois" tabindex="-1">4.4 État actuel (honnête) et positionnement cible à 12 mois <a class="header-anchor" href="#_4-4-etat-actuel-honnete-et-positionnement-cible-a-12-mois" aria-label="Permalink to &quot;4.4 État actuel (honnête) et positionnement cible à 12 mois&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Dimension</th><th>Aujourd&#39;hui (05/11/2026)</th><th>Cible (11/2027)</th></tr></thead><tbody><tr><td>Produit</td><td>Phases 0 à 3 faites, phase 4 à faire ; validations sur matériel physique en attente</td><td>Validé sur matériel réel, phase 4 partielle (menu QR, poids, onboarding)</td></tr><tr><td>Société et identité éditeur</td><td><strong>À créer</strong> ; contact public sur une adresse Gmail personnelle</td><td>Société, domaine, adresse de contact et mentions légales professionnelles</td></tr><tr><td>Hébergement</td><td><strong>Aucun</strong> en production</td><td>Hébergement de production en Europe, supervision, sauvegardes</td></tr><tr><td>France — fiscal</td><td>Attestation « MODÈLE » ; NF525 non engagée ; PA simulée</td><td>Attestation éditeur signée dès la création ; <strong>certification NF525 obtenue ou en audit</strong> ; PA contractualisée et e-reporting réel avant le 01/09/2027</td></tr><tr><td>Tunisie — fiscal</td><td>NACEF en attente du cahier des charges</td><td><strong>Homologué</strong>, présent sur jibaya.tn, avant la vague du 01/07/2027 — ou partenariat avec un fournisseur homologué</td></tr><tr><td>Références</td><td>Aucune</td><td>10 pilotes publiés, 110 clients payants</td></tr><tr><td>Image</td><td>« Produit technique prometteur »</td><td>TN : « la caisse homologuée moderne » · FR : « la caisse indépendante sans commission prête pour 2027 »</td></tr></tbody></table><hr><h2 id="_5-segments-et-personas-qui-acheter-en-premier" tabindex="-1">5. Segments et personas : qui acheter en premier <a class="header-anchor" href="#_5-segments-et-personas-qui-acheter-en-premier" aria-label="Permalink to &quot;5. Segments et personas : qui acheter en premier&quot;">​</a></h2><p>Ordre de priorité : <strong>vendabilité immédiate</strong> (pas de blocage réglementaire), <strong>valeur des différenciateurs</strong>, <strong>coût de vente</strong>.</p><h3 id="_5-1-tunisie" tabindex="-1">5.1 Tunisie <a class="header-anchor" href="#_5-1-tunisie" aria-label="Permalink to &quot;5.1 Tunisie&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Rang</th><th>Segment</th><th>Persona (fictif)</th><th>Job to be done</th><th>Objections</th><th>Réponse</th></tr></thead><tbody><tr><td>1</td><td><strong>Supérette, épicerie fine, boutique</strong> (1 point de vente, 2-6 salariés) — non soumise à NACEF</td><td>Hédi, 45 ans, supérette à l&#39;Ariana (contact : <a href="mailto:hedi@exemple.tn" target="_blank" rel="noreferrer">hedi@exemple.tn</a>)</td><td>« Savoir ce que j&#39;ai en stock, suivre la karna de mes clients et voir si ma caisse tombe juste quand je ne suis pas là. »</td><td>« Mon cahier suffit » · « 29 DT chez Kesti » · « Et si internet coupe ? »</td><td>Démo des écarts de caisse et de l&#39;ardoise plafonnée ; Essentiel à 39 DT ; démonstration box débranchée</td></tr><tr><td>2</td><td><strong>Petite chaîne de 3 à 10 points de vente</strong> (snacks, pâtisseries, boutiques franchisées)</td><td>Mourad, 38 ans, 4 snacks à Sousse</td><td>« Piloter mes magasins depuis mon téléphone et repérer les annulations suspectes. »</td><td>« Combien pour 4 magasins ? » · « Mes gérants ne sauront pas »</td><td>Sur mesure avec devis transparent ; formation sur place ; anti-fraude par caissier</td></tr><tr><td>3</td><td><strong>Café et salon de thé personne physique au régime réel</strong> (vague du 01/07/2027)</td><td>Salma, 33 ans, café-salon de thé à La Marsa</td><td>« Être en règle NACEF sans changer toute mon organisation, et que les serveurs prennent les commandes sur leur téléphone. »</td><td>« Êtes-vous homologués ? » (bloquant) · « Al-Makhzan a le menu QR »</td><td>Vendre <strong>après homologation</strong> ; préinscription dès le T1 2027 avec tarif garanti</td></tr><tr><td>4</td><td><strong>Restaurant de quartier personne morale</strong> (déjà obligé)</td><td>—</td><td>Idem, urgence</td><td>Bloquant tant que NACEF n&#39;est pas obtenu</td><td>Uniquement via un partenaire homologué ou après homologation</td></tr></tbody></table><h3 id="_5-2-france" tabindex="-1">5.2 France <a class="header-anchor" href="#_5-2-france" aria-label="Permalink to &quot;5.2 France&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Rang</th><th>Segment</th><th>Persona (fictif)</th><th>Job to be done</th><th>Objections</th><th>Réponse</th></tr></thead><tbody><tr><td>1</td><td><strong>Épicerie fine, cave, traiteur, primeur haut de gamme</strong></td><td>Claire, 41 ans, épicerie fine à Lyon</td><td>« Une caisse simple qui gère le stock, la fidélité et les titres-restaurant, et qui me met en règle pour l&#39;e-reporting sans que mon comptable me relance. »</td><td>« Êtes-vous certifiés NF525 ? » · « Qui vient installer ? » · « Vente au poids ? »</td><td>Attestation éditeur + calendrier NF525 ; installation à distance guidée ; étiquettes de balance déjà lues, balance connectée en phase 4</td></tr><tr><td>2</td><td><strong>Restaurant de quartier, brasserie, pizzeria (20-60 couverts)</strong></td><td>Karim, 36 ans, restaurant de 40 couverts à Marseille</td><td>« Que la salle et la cuisine se parlent même quand la box plante, sans payer 1,75 % sur chaque addition ni acheter des iPad. »</td><td>« Je suis engagé encore 14 mois » · « Et le TPE ? »</td><td>Offre fondateurs démarrant à la fin de l&#39;engagement ; TPE de sa banque conservé, montant saisi</td></tr><tr><td>3</td><td><strong>Réseau de 3 à 10 points de vente</strong> (boulangeries, snacks, franchises naissantes)</td><td>Un franchiseur de 6 boulangeries</td><td>« Mêmes prix et mêmes produits partout, chiffres comparés, ma marque sur l&#39;app. »</td><td>« Intégration à notre ERP ? » · « Pérennité de l&#39;éditeur ? »</td><td>Sur mesure, marque blanche, exports comptables ; contrat avec réversibilité des données</td></tr><tr><td>4</td><td><strong>Commerce de détail généraliste</strong> (boutique de cadeaux, bazar, librairie)</td><td>—</td><td>Caisse et stock simples</td><td>Concurrence gratuite (Hiboutik, SumUp)</td><td>Pas de prospection active la première année ; inbound seulement</td></tr></tbody></table><hr><h2 id="_6-tarification" tabindex="-1">6. Tarification <a class="header-anchor" href="#_6-tarification" aria-label="Permalink to &quot;6. Tarification&quot;">​</a></h2><h3 id="_6-1-analyse-de-la-grille-actuelle" tabindex="-1">6.1 Analyse de la grille actuelle <a class="header-anchor" href="#_6-1-analyse-de-la-grille-actuelle" aria-label="Permalink to &quot;6.1 Analyse de la grille actuelle&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Critère</th><th>Constat</th><th>Verdict</th></tr></thead><tbody><tr><td>Cohérence interne</td><td>Paliers clairs : 1 → 3 → 6 appareils, modules ajoutés par métier ; appareil supplémentaire 9 € ; annuel = 10 mois payés</td><td>Bon</td></tr><tr><td>France</td><td>29 € = Tactill annuel, sous SumUp Plus (49 €) ; 79 € Restaurant = Innovorder Starter et sous Lightspeed Basic (89 €), avec 6 appareils inclus là où Square facture 59 € par point de vente et le KDS à part</td><td>Bon, plutôt bas pour Restaurant</td></tr><tr><td>Tunisie</td><td>29 / 49 / 79 € ≈ <strong>99 / 167 / 269 DT</strong> au taux de 3,4 de la page publique, contre 29 DT (Kesti) et 79 DT (Al-Makhzan)</td><td><strong>Hors marché</strong> : 3 à 4 fois l&#39;ancrage</td></tr><tr><td>Devise</td><td>Facturation en euros, dinars « indicatifs » : un commerçant tunisien paie en dinars ; payer une société étrangère en devises suppose une opération de change et peut entraîner une retenue à la source</td><td><strong>Bloquant</strong> [Non vérifié : règles BCT et retenue sur prestations de non-résidents, à confirmer avec un conseiller fiscal tunisien]</td></tr><tr><td>TVA</td><td>Prix affichés HT. France : TVA 20 % sur l&#39;abonnement ; Tunisie : TVA au taux normal (19 % [Non vérifié le 05/11/2026]) si facturation locale</td><td>À afficher clairement TTC pour les micro-entrepreneurs français non assujettis</td></tr><tr><td>Matériel</td><td>Non vendu ; « sur le matériel que vous avez déjà »</td><td>Argument fort, mais le commerçant sans matériel n&#39;a pas de solution</td></tr><tr><td>Coûts variables cachés</td><td>E-reporting via PA : 110-300 € HT/an par entreprise au tarif public de B2Brouter (actions terrain), soit <strong>9 à 25 €/mois</strong> — jusqu&#39;à 86 % du prix d&#39;Essentiel</td><td><strong>À négocier en volume avant de l&#39;inclure partout</strong></td></tr></tbody></table><p><strong>Élasticité [Estimation]</strong> : en Tunisie, la sensibilité au prix est forte sous 100 DT ; au-delà, l&#39;achat se fait sur la valeur prouvée (homologation, anti-fraude, multi-magasins) et souvent via un revendeur. En France, l&#39;écart entre 29 et 49 € pèse peu face au coût d&#39;un changement de caisse ; ce qui fait signer, c&#39;est l&#39;absence d&#39;engagement, l&#39;absence de commission et la conformité.</p><h3 id="_6-2-grille-recommandee-—-tunisie-en-dinars-ht" tabindex="-1">6.2 Grille recommandée — Tunisie (en dinars, HT) <a class="header-anchor" href="#_6-2-grille-recommandee-—-tunisie-en-dinars-ht" aria-label="Permalink to &quot;6.2 Grille recommandée — Tunisie (en dinars, HT)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Formule</th><th>Mensuel</th><th>Annuel (10 mois)</th><th>Inclus</th><th>Positionnement</th></tr></thead><tbody><tr><td><strong>Essentiel</strong></td><td><strong>39 DT</strong></td><td>390 DT</td><td>1 magasin, 1 appareil, ventes, stock, Z, rapports</td><td>Au-dessus de Kesti (+10 DT justifiés par l&#39;offline et l&#39;anti-fraude), commerce de détail</td></tr><tr><td><strong>Commerce</strong></td><td><strong>69 DT</strong></td><td>690 DT</td><td>3 appareils, fidélité, <strong>ardoise</strong>, fournisseurs, inventaires, anti-fraude</td><td>Sous Al-Makhzan, cœur de cible supérette</td></tr><tr><td><strong>Restaurant</strong></td><td><strong>99 DT</strong></td><td>990 DT</td><td>6 appareils, salle, écrans cuisine, pourboires, food-cost ; <strong>module NACEF inclus une fois homologué</strong></td><td>20 DT au-dessus d&#39;Al-Makhzan, justifiés par l&#39;homologation et les 6 appareils</td></tr><tr><td><strong>Sur mesure</strong></td><td>Devis (repère : 79 DT par magasin au-delà du premier)</td><td>—</td><td>Plusieurs magasins, marque blanche</td><td>Chaînes et franchises</td></tr><tr><td>Appareil supplémentaire</td><td><strong>15 DT</strong></td><td>150 DT</td><td>—</td><td>—</td></tr><tr><td>Installation et formation sur place</td><td>150 DT (offerte en annuel)</td><td>—</td><td>Paramétrage du catalogue, appairage, formation 2 h</td><td>Pratique locale (Wasel, Al-Makhzan incluent l&#39;installation)</td></tr></tbody></table><p><strong>Facturation locale</strong> : trois options, à trancher (§10) — (a) <strong>société tunisienne</strong> (SUARL) qui facture en dinars avec TVA et encaisse par virement, Flouci ou Konnect ; (b) <strong>distributeur tunisien</strong> qui achète les licences en euros et revend en dinars avec sa marge (25-35 % [Estimation]) ; (c) facturation en euros depuis la société française, à réserver aux clients disposant de devises (exportateurs, franchises étrangères). Recommandation : (b) pour démarrer vite, (a) dès 50 clients.</p><p><strong>Option licence</strong> (réponse à Wasel) : à <strong>ne pas</strong> proposer ; préférer « annuel payé d&#39;avance » à 390 DT, proche d&#39;une licence dans la tête du commerçant, avec mises à jour et homologation incluses.</p><h3 id="_6-3-grille-recommandee-—-france-en-euros-ht" tabindex="-1">6.3 Grille recommandée — France (en euros, HT) <a class="header-anchor" href="#_6-3-grille-recommandee-—-france-en-euros-ht" aria-label="Permalink to &quot;6.3 Grille recommandée — France (en euros, HT)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Formule</th><th>Mensuel</th><th>Annuel</th><th>Inclus</th><th>Changement proposé</th></tr></thead><tbody><tr><td><strong>Essentiel</strong></td><td><strong>29 €</strong></td><td>290 €</td><td>1 appareil</td><td>E-reporting en option à 5 €/mois tant que le coût PA n&#39;est pas négocié</td></tr><tr><td><strong>Commerce</strong></td><td><strong>49 €</strong></td><td>490 €</td><td>3 appareils, titres-restaurant, e-reporting</td><td>E-reporting inclus (argument 2027)</td></tr><tr><td><strong>Restaurant</strong></td><td><strong>79 €</strong>, puis <strong>89 €</strong> après certification NF525</td><td>790 € → 890 €</td><td>6 appareils, salle, cuisine, pourboires, food-cost, e-reporting</td><td>Hausse liée à une preuve, annoncée à l&#39;avance ; clients existants protégés 24 mois</td></tr><tr><td><strong>Sur mesure</strong></td><td>Devis (repère : 59 € par magasin supplémentaire)</td><td>—</td><td>Multi-magasins, marque blanche</td><td>—</td></tr><tr><td>Appareil supplémentaire</td><td><strong>9 €</strong></td><td>90 €</td><td>—</td><td>Inchangé : très compétitif face aux 15 € du KDS Square</td></tr><tr><td><strong>Offre fondateurs</strong></td><td>−30 % pendant 12 mois</td><td>—</td><td>30 premiers commerces, contre témoignage et autorisation de captures</td><td>Nouveau</td></tr><tr><td>Mise en service à distance</td><td>0 € (visio de 1 h)</td><td>—</td><td>Import CSV du catalogue, appairage</td><td>Nouveau</td></tr><tr><td>Installation sur site</td><td>190 € (Île-de-France, Lyon, Marseille via partenaire)</td><td>—</td><td>Matériel branché, formation de l&#39;équipe</td><td>Nouveau, réalisée par un revendeur</td></tr></tbody></table><h3 id="_6-4-options-transverses" tabindex="-1">6.4 Options transverses <a class="header-anchor" href="#_6-4-options-transverses" aria-label="Permalink to &quot;6.4 Options transverses&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Option</th><th>Recommandation</th></tr></thead><tbody><tr><td><strong>Matériel</strong></td><td>Pas de stock ni de revente en propre la première année. Packs proposés par un revendeur partenaire (tablette Android 10″, imprimante thermique 80 mm réseau, tiroir RJ11, douchette), avec liste de matériel validé publiée après la campagne de validation physique. Repère France : kits SumUp 549-649 € HT, Tactill Box 1 189 €. Repère Tunisie : à relever chez deux revendeurs [Non vérifié].</td></tr><tr><td><strong>Support</strong></td><td>Inclus : email + WhatsApp (TN) aux heures d&#39;ouverture, base d&#39;aide en trois langues. Option « support prioritaire soir et week-end » à 10 €/mois ou 30 DT/mois pour la restauration, à lancer quand une astreinte existe.</td></tr><tr><td><strong>Formation</strong></td><td>Vidéos courtes en trois langues tirées de la démo (106 écrans déjà produits) ; formation sur site payante via revendeur.</td></tr><tr><td><strong>Essai</strong></td><td>14 jours sans carte bancaire (inchangé) en France ; <strong>30 jours en Tunisie</strong> pour s&#39;aligner sur Kesti (1 mois) et Al-Makhzan (garantie 30 jours).</td></tr><tr><td><strong>Remises</strong></td><td>Annuel = 2 mois offerts (pratique du marché des deux côtés) ; multi-magasins −15 % à partir de 3 magasins ; associations de commerçants et franchises −10 % ; <strong>jamais</strong> de remise sans durée ni contrepartie (témoignage, annuel, parrainage).</td></tr><tr><td><strong>Parrainage</strong></td><td>Un mois offert au parrain et au filleul : canal naturel dans les rues commerçantes et entre restaurateurs.</td></tr><tr><td><strong>Rachat d&#39;engagement</strong> (FR)</td><td>Pour un client encore engagé ailleurs : Vendora gratuit jusqu&#39;à la fin de son contrat, dans la limite de 3 mois.</td></tr></tbody></table><h3 id="_6-5-impact-sur-le-revenu" tabindex="-1">6.5 Impact sur le revenu <a class="header-anchor" href="#_6-5-impact-sur-le-revenu" aria-label="Permalink to &quot;6.5 Impact sur le revenu&quot;">​</a></h3><p>Hypothèses [Estimation] : Tunisie 40 % Essentiel, 35 % Commerce, 25 % Restaurant, 0,3 appareil supplémentaire par client, soit un revenu moyen de <strong>69 DT ≈ 20,5 €</strong> par mois (1 € = 3,37 DT) ; France 30 % Essentiel, 40 % Commerce, 30 % Restaurant, 0,5 appareil supplémentaire, soit <strong>56,5 €</strong> par mois. Hors remise fondateurs et hors annuel (l&#39;annuel réduit le revenu de 17 % mais l&#39;encaisse d&#39;avance).</p><table tabindex="0"><thead><tr><th>Clients</th><th>Tunisie — MRR</th><th>France — MRR</th><th>Mix 60 % TN / 40 % FR — MRR</th><th>ARR du mix</th></tr></thead><tbody><tr><td><strong>50</strong></td><td>3 450 DT ≈ 1 025 €</td><td>2 825 €</td><td>615 + 1 130 = <strong>1 745 €</strong></td><td>~20 900 €</td></tr><tr><td><strong>200</strong></td><td>13 800 DT ≈ 4 095 €</td><td>11 300 €</td><td>2 460 + 4 520 = <strong>6 980 €</strong></td><td>~83 800 €</td></tr><tr><td><strong>500</strong></td><td>34 500 DT ≈ 10 240 €</td><td>28 250 €</td><td>6 140 + 11 300 = <strong>17 440 €</strong></td><td>~209 300 €</td></tr></tbody></table><p>Avec la <strong>grille actuelle appliquée en Tunisie</strong> (99 / 167 / 269 DT), le revenu moyen serait de ~190 DT, mais l&#39;hypothèse de conversion ne tient pas : à 50 clients tunisiens, il faudrait les trouver parmi les rares commerçants prêts à payer 2,5 fois Al-Makhzan [Estimation].</p><p><strong>Coûts variables par client [Estimation]</strong> : hébergement et stockage 1-2 €/mois, emails et SMS 0,5 €, PA 9-25 € (France, avant négociation), commission revendeur 25-35 % (Tunisie), paiement en ligne 1,3-3 %. <strong>Marge brute visée : 75 % en France, 60 % en Tunisie via revendeur.</strong></p><hr><h2 id="_7-canaux-et-processus-de-vente" tabindex="-1">7. Canaux et processus de vente <a class="header-anchor" href="#_7-canaux-et-processus-de-vente" aria-label="Permalink to &quot;7. Canaux et processus de vente&quot;">​</a></h2><h3 id="_7-1-canaux-par-marche" tabindex="-1">7.1 Canaux par marché <a class="header-anchor" href="#_7-1-canaux-par-marche" aria-label="Permalink to &quot;7.1 Canaux par marché&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Canal</th><th>Tunisie</th><th>France</th><th>Rémunération proposée [Estimation]</th></tr></thead><tbody><tr><td><strong>Vente directe</strong> (fondateur, puis un commercial terrain)</td><td>Pilotes et chaînes de 3-10 magasins ; tournées par quartier commerçant</td><td>Pilotes, réseaux de 3-10 points de vente</td><td>Salaire + variable</td></tr><tr><td><strong>Revendeurs / installateurs de matériel</strong></td><td><strong>Canal n° 1</strong> : ils vendent déjà caisses, imprimantes et TPE et cherchent une offre homologuée moderne</td><td>Canal n° 2 : revendeurs régionaux de caisses NF525 lassés des engagements</td><td>30 % récurrent la 1re année, 20 % ensuite, ou marge de revente</td></tr><tr><td><strong>Experts-comptables</strong></td><td>Comptables de quartier : prescripteurs de la caisse fiscale</td><td><strong>Canal n° 1</strong> : 21 611 inscrits, concernés par l&#39;e-reporting et le FEC</td><td>Commission d&#39;apport 20 % la 1re année ou accès gratuit à un tableau de bord « cabinet »</td></tr><tr><td><strong>Fournisseurs de paiement</strong></td><td>Flouci, Konnect, Paymee : co-marketing auprès de leurs marchands (« caisse compatible QR »)</td><td>Banques et PSP de TPE : recommandation croisée</td><td>Accord de référencement, sans flux financier au départ</td></tr><tr><td><strong>Plateforme agréée</strong></td><td>—</td><td>La PA partenaire (iopole, B2Brouter) peut référencer les caisses compatibles</td><td>Échange de visibilité</td></tr><tr><td><strong>Fournisseur homologué NACEF</strong></td><td>Alternative à l&#39;homologation propre : s&#39;associer à un fournisseur déjà agréé (module de sécurisation)</td><td>—</td><td>Partage de revenu à négocier</td></tr><tr><td><strong>Comparateurs et marketplaces</strong></td><td>Faible</td><td>Capterra, GetApp, tool-advisor, independant.io (fiche + avis)</td><td>Gratuit à payant au clic</td></tr><tr><td><strong>Franchiseurs et réseaux</strong></td><td>Salons de la franchise, réseaux de snacks</td><td>Fédérations (épiceries fines, boulangers)</td><td>Conditions groupe (−10 %)</td></tr></tbody></table><h3 id="_7-2-cycle-de-vente" tabindex="-1">7.2 Cycle de vente <a class="header-anchor" href="#_7-2-cycle-de-vente" aria-label="Permalink to &quot;7.2 Cycle de vente&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Étape</th><th>Tunisie</th><th>France</th><th>Outil existant</th></tr></thead><tbody><tr><td>Premier contact</td><td>Visite en boutique, WhatsApp, revendeur</td><td>Formulaire de devis, recommandation du comptable</td><td>Page publique, formulaire de devis vers la console</td></tr><tr><td>Démo</td><td>15 min sur la tablette du commerçant, <strong>box débranchée</strong></td><td>20 min en visio ou sur place</td><td>Visite guidée de 106 écrans ; mode démo des apps</td></tr><tr><td>Essai</td><td>30 jours</td><td>14 jours</td><td>Essai libre créé dans la console (lot C3)</td></tr><tr><td>Mise en service</td><td>Sur place, 1-2 h</td><td>À distance, 1 h</td><td>Code d&#39;appairage, import CSV</td></tr><tr><td>Signature</td><td>Bon de commande, paiement annuel encouragé</td><td>Abonnement en ligne</td><td>Devis et factures de la console (lot C6)</td></tr><tr><td>Durée du cycle [Estimation]</td><td>1-3 semaines (indépendant) ; 1-2 mois (chaîne)</td><td>2-6 semaines ; jusqu&#39;à la fin de l&#39;engagement en cours</td><td>—</td></tr></tbody></table><h3 id="_7-3-onboarding-et-support" tabindex="-1">7.3 Onboarding et support <a class="header-anchor" href="#_7-3-onboarding-et-support" aria-label="Permalink to &quot;7.3 Onboarding et support&quot;">​</a></h3><p>Objectif « première vente en moins de 30 minutes » (profil, import CSV du catalogue, appairage, ticket de test), appel de suivi à J+7, revue des rapports avec le propriétaire à J+30 — c&#39;est là qu&#39;il voit la valeur anti-fraude. Support : aide en ligne en trois langues et diagnostic matériel intégré (N0), WhatsApp en Tunisie et email en France sous 4 h ouvrées (N1), accès support en lecture seule tracé de la console sous 1 jour ouvré (N2). Comme la caisse continue hors ligne, un incident serveur n&#39;arrête jamais un commerce, ce qui allège l&#39;astreinte des premiers mois.</p><h3 id="_7-5-cout-d-acquisition-cible" tabindex="-1">7.5 Coût d&#39;acquisition cible <a class="header-anchor" href="#_7-5-cout-d-acquisition-cible" aria-label="Permalink to &quot;7.5 Coût d&#39;acquisition cible&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>Tunisie</th><th>France</th></tr></thead><tbody><tr><td>Revenu moyen mensuel</td><td>~20,5 €</td><td>~56,5 €</td></tr><tr><td>Marge brute</td><td>60 %</td><td>75 %</td></tr><tr><td>Churn mensuel visé</td><td>3 %</td><td>2 %</td></tr><tr><td>Valeur vie client (marge)</td><td>20,5 × 0,6 / 0,03 ≈ <strong>410 €</strong></td><td>56,5 × 0,75 / 0,02 ≈ <strong>2 120 €</strong></td></tr><tr><td><strong>CAC maximal</strong> (ratio 3)</td><td><strong>~135 € (≈ 450 DT)</strong></td><td><strong>~700 €</strong></td></tr><tr><td>Retour sur CAC</td><td>&lt; 11 mois</td><td>&lt; 17 mois</td></tr></tbody></table><p>Conséquence : en Tunisie, seul un <strong>canal à coût variable</strong> (revendeurs commissionnés, parrainage, prospection groupée par rue) est rentable ; la publicité payante y sera marginale. En France, on peut se permettre de la recherche payante ciblée et des déplacements, mais le canal comptable reste le plus rentable.</p><hr><h2 id="_8-marketing" tabindex="-1">8. Marketing <a class="header-anchor" href="#_8-marketing" aria-label="Permalink to &quot;8. Marketing&quot;">​</a></h2><h3 id="_8-1-messages" tabindex="-1">8.1 Messages <a class="header-anchor" href="#_8-1-messages" aria-label="Permalink to &quot;8.1 Messages&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Marché</th><th>Message principal</th><th>Messages de soutien</th></tr></thead><tbody><tr><td>Tunisie</td><td>« La caisse qui ne s&#39;arrête jamais — même quand internet coupe. » (en arabe et en français)</td><td>« Votre karna enfin sous contrôle » · « Vos magasins dans votre poche » · « Homologuée NACEF » (uniquement une fois obtenue)</td></tr><tr><td>France</td><td>« Sans commission, sans engagement, sans iPad imposé. »</td><td>« Continue sans internet » · « Prête pour l&#39;e-reporting 2027 » · « Titres-restaurant et pourboires gérés »</td></tr></tbody></table><p>Règle : ne jamais afficher une conformité non obtenue ; écrire « homologation en cours » ou « certification NF525 en cours » avec la date de dépôt.</p><h3 id="_8-2-preuves" tabindex="-1">8.2 Preuves <a class="header-anchor" href="#_8-2-preuves" aria-label="Permalink to &quot;8.2 Preuves&quot;">​</a></h3><ol><li><strong>Démo en images</strong> déjà publiée (106 écrans, filtres par appareil, langue, thème) — à compléter par une <strong>vidéo de 60 secondes « box débranchée en plein service »</strong>, l&#39;argument le plus fort et le plus visuel.</li><li><strong>Essai</strong> de 14 jours (FR) / 30 jours (TN).</li><li><strong>Page publique « Ce qui marche sans internet »</strong> avec les limites explicites (paiement carte en ligne, e-reporting différé) : personne ne le fait (étude concurrentielle §3.3).</li><li><strong>Études de cas</strong> des pilotes (avant / après : écarts de caisse, temps de clôture).</li><li>Attestation éditeur téléchargeable, puis certificat NF525 ; numéro d&#39;homologation NACEF.</li></ol><h3 id="_8-3-contenus-seo-et-reseaux" tabindex="-1">8.3 Contenus, SEO et réseaux <a class="header-anchor" href="#_8-3-contenus-seo-et-reseaux" aria-label="Permalink to &quot;8.3 Contenus, SEO et réseaux&quot;">​</a></h3><ul><li><strong>Tunisie</strong> : guide « Caisse enregistreuse obligatoire : êtes-vous concerné en 2027 ? » en français et en arabe ; pages par métier ; vidéos courtes en dialecte sur Facebook, Instagram et TikTok ; suivi par WhatsApp Business.</li><li><strong>France</strong> : guide « E-reporting 2027 pour les commerçants » ; comparatifs honnêtes (« Vendora ou SumUp ? ») ; calculateur « Combien vous coûte votre commission carte ? » ; pages par métier (épicerie fine, boulangerie, restaurant) ; LinkedIn pour les comptables et franchiseurs, Instagram et groupes Facebook pour les restaurateurs.</li></ul><h3 id="_8-4-salons-et-evenements" tabindex="-1">8.4 Salons et événements <a class="header-anchor" href="#_8-4-salons-et-evenements" aria-label="Permalink to &quot;8.4 Salons et événements&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Événement</th><th>Lieu</th><th>Date</th><th>Usage</th><th>Vérification</th></tr></thead><tbody><tr><td><strong>Sirha</strong></td><td>Lyon, Eurexpo</td><td>21-25/01/2027</td><td>Visite et rendez-vous, pas de stand la 1re année</td><td><a href="https://www.journaldespalaces.com/communique-78163-france-evenements-sirha-lyon-2027-une-vision-renouvelee-pour-porter-les-ambitions-du-food-service-mondial.html" target="_blank" rel="noreferrer">Journal des Palaces</a> <strong>[Tiers]</strong></td></tr><tr><td>Franchise Expo Paris</td><td>Paris</td><td>Mars 2027 (habituel)</td><td>Rencontre de franchiseurs</td><td>[Non vérifié]</td></tr><tr><td>Congrès de l&#39;Ordre des experts-comptables</td><td>France</td><td>Automne 2027 (habituel)</td><td>Canal comptable</td><td>[Non vérifié]</td></tr><tr><td>IFSA Africa (agroalimentaire)</td><td>Tunis, Le Kram</td><td>Juin (édition 2026 du 9 au 11/06)</td><td>Revendeurs, distribution alimentaire</td><td>Édition 2027 [Non vérifié]</td></tr><tr><td>Tunisia Franchise Show / Tunis-Medfranchise</td><td>Tunis</td><td>Éditions 2023-2024 ; 2027 non annoncée</td><td>Chaînes et franchises</td><td>[Non vérifié]</td></tr><tr><td>Réunions de la Chambre nationale des cafés, chambres de commerce régionales (CCI Tunis, Sousse, Sfax)</td><td>Tunisie</td><td>À programmer</td><td>Ateliers « obligation de caisse »</td><td>À démarcher</td></tr></tbody></table><h3 id="_8-5-budget-indicatif-12-mois-estimation" tabindex="-1">8.5 Budget indicatif (12 mois) [Estimation] <a class="header-anchor" href="#_8-5-budget-indicatif-12-mois-estimation" aria-label="Permalink to &quot;8.5 Budget indicatif (12 mois) [Estimation]&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Poste</th><th>Tunisie</th><th>France</th></tr></thead><tbody><tr><td>Vidéos, traductions, contenus</td><td>3 000 DT</td><td>2 500 €</td></tr><tr><td>Publicité (Meta TN ; recherche payante FR)</td><td>6 000 DT</td><td>9 000 €</td></tr><tr><td>Déplacements, démonstrations, salons (visites)</td><td>6 000 DT</td><td>5 000 €</td></tr><tr><td>Matériel de démo (2 tablettes, imprimante, tiroir, douchette par pays)</td><td>2 500 DT</td><td>1 200 €</td></tr><tr><td>Commissions revendeurs et comptables</td><td>variables (§7.1)</td><td>variables</td></tr><tr><td><strong>Total hors commissions</strong></td><td><strong>~17 500 DT (~5 200 €)</strong></td><td><strong>~17 700 €</strong></td></tr></tbody></table><hr><h2 id="_9-plan-12-mois-par-marche" tabindex="-1">9. Plan 12 mois par marché <a class="header-anchor" href="#_9-plan-12-mois-par-marche" aria-label="Permalink to &quot;9. Plan 12 mois par marché&quot;">​</a></h2><h3 id="_9-1-prerequis-dependances-terrain" tabindex="-1">9.1 Prérequis (dépendances terrain) <a class="header-anchor" href="#_9-1-prerequis-dependances-terrain" aria-label="Permalink to &quot;9.1 Prérequis (dépendances terrain)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Prérequis</th><th>Débloque</th><th>Échéance visée</th><th>Responsable</th></tr></thead><tbody><tr><td><strong>Société éditrice</strong> + nom de domaine + adresse de contact professionnelle</td><td>Attestation éditeur, factures, contrats PA et paiement, mentions légales</td><td><strong>Décembre 2026</strong></td><td>Ahmed</td></tr><tr><td><strong>Hébergement de production</strong> (Europe) + SMTP + adresse HTTPS de l&#39;API</td><td>Essais réels, tarifs en direct sur la page publique, devis vers la console</td><td>Décembre 2026</td><td>Ahmed</td></tr><tr><td>Validation sur <strong>matériel physique</strong> (3 appareils, imprimante, tiroir, douchette)</td><td>Liste de matériel compatible, pilotes</td><td>Décembre 2026</td><td>Ahmed</td></tr><tr><td><strong>Cahier des charges NACEF</strong> (connexion tunisienne) + appel DGI</td><td>Chiffrage et calendrier d&#39;homologation</td><td>Décembre 2026</td><td>Ahmed ou un proche sur place</td></tr><tr><td>Grille en dinars dans la console (devise par marché)</td><td>Vente en Tunisie</td><td>Janvier 2027</td><td>Produit</td></tr><tr><td>Entité ou distributeur de facturation en Tunisie</td><td>Encaissement en dinars</td><td>Février 2027</td><td>Ahmed</td></tr><tr><td><strong>Contrat PA</strong> (iopole ou B2Brouter) + prix volume</td><td>E-reporting réel, inclusion dans les formules</td><td><strong>Avant fin mars 2027</strong></td><td>Ahmed</td></tr><tr><td>Dossier <strong>NF525</strong> (organisme, audit)</td><td>Certification, hausse du prix Restaurant</td><td>Dépôt T2 2027</td><td>Ahmed + produit</td></tr><tr><td>Homologation <strong>NACEF</strong></td><td>Vente à la restauration tunisienne</td><td>Avant 07/2027 (vague personnes physiques)</td><td>Produit + terrain</td></tr><tr><td>Comptes marchands Flouci / Konnect</td><td>Paiement QR réel</td><td>T1 2027</td><td>Ahmed</td></tr></tbody></table><h3 id="_9-2-jalons-trimestriels" tabindex="-1">9.2 Jalons trimestriels <a class="header-anchor" href="#_9-2-jalons-trimestriels" aria-label="Permalink to &quot;9.2 Jalons trimestriels&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Trimestre</th><th>Tunisie</th><th>France</th></tr></thead><tbody><tr><td><strong>T1 : nov. 2026 → janv. 2027</strong></td><td>Société / distributeur choisi ; cahier des charges NACEF ; 6 pilotes en commerce de détail (Grand Tunis) ; 2 revendeurs approchés ; grille en DT publiée</td><td>Société créée, attestation éditeur ; hébergement ; 4 pilotes (2 épiceries fines, 2 restaurants) ; visite du Sirha ; 10 cabinets comptables contactés</td></tr><tr><td><strong>T2 : févr. → avr. 2027</strong></td><td>2 revendeurs signés ; 25 clients payants ; dossier NACEF déposé ; préinscriptions cafés et restaurants « tarif garanti »</td><td>Contrat PA ; e-reporting réel en recette ; offre fondateurs ouverte ; 15 clients payants ; fiches sur les comparateurs</td></tr><tr><td><strong>T3 : mai → juil. 2027</strong></td><td>Homologation visée ; lancement restauration à la vague du 01/07/2027 ; 45 clients</td><td>Dossier NF525 en audit ; campagne « e-reporting 2027 » avec les comptables ; 28 clients</td></tr><tr><td><strong>T4 : août → oct. 2027</strong></td><td>70 clients ; premier réseau de 3-10 magasins ; 1 commercial terrain</td><td>E-reporting obligatoire le 01/09/2027 : pic de demande ; 40 clients ; prix Restaurant à 89 € si certifié</td></tr></tbody></table><h3 id="_9-3-kpi-et-objectifs-chiffres-fin-octobre-2027" tabindex="-1">9.3 KPI et objectifs chiffrés (fin octobre 2027) <a class="header-anchor" href="#_9-3-kpi-et-objectifs-chiffres-fin-octobre-2027" aria-label="Permalink to &quot;9.3 KPI et objectifs chiffrés (fin octobre 2027)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>KPI</th><th>Tunisie — base</th><th>Tunisie — haut</th><th>France — base</th><th>France — haut</th></tr></thead><tbody><tr><td>Clients payants</td><td>70</td><td>150</td><td>40</td><td>90</td></tr><tr><td>dont restauration</td><td>15 (si NACEF au T3)</td><td>60</td><td>15</td><td>40</td></tr><tr><td>MRR</td><td>~4 800 DT (~1 430 €)</td><td>~10 400 DT (~3 080 €)</td><td>~2 260 € (après remises fondateurs : ~1 750 €)</td><td>~5 090 €</td></tr><tr><td>Churn mensuel</td><td>&lt; 3 %</td><td>&lt; 2,5 %</td><td>&lt; 2 %</td><td>&lt; 1,5 %</td></tr><tr><td>Conversion essai → payant</td><td>≥ 40 % (avec démo sur place)</td><td>≥ 50 %</td><td>≥ 25 %</td><td>≥ 35 %</td></tr><tr><td>Délai de mise en service</td><td>&lt; 2 h sur place</td><td>—</td><td>&lt; 1 h à distance</td><td>—</td></tr><tr><td>Part des ventes par partenaires</td><td>≥ 50 %</td><td>≥ 60 %</td><td>≥ 30 %</td><td>≥ 40 %</td></tr></tbody></table><p>Total scénario de base : <strong>110 clients, ~3 700 € de MRR à fin octobre 2027</strong> (~3 200 € tant que les remises fondateurs courent) ; scénario haut : 240 clients, ~8 150 € [Estimation]. Indicateurs produit à suivre en parallèle : ventes faites hors ligne, incidents de synchronisation, temps moyen d&#39;une vente (&lt; 100 ms par action), tickets de support par client.</p><hr><h2 id="_10-risques-et-parades-decisions-a-prendre" tabindex="-1">10. Risques et parades ; décisions à prendre <a class="header-anchor" href="#_10-risques-et-parades-decisions-a-prendre" aria-label="Permalink to &quot;10. Risques et parades ; décisions à prendre&quot;">​</a></h2><h3 id="_10-1-risques" tabindex="-1">10.1 Risques <a class="header-anchor" href="#_10-1-risques" aria-label="Permalink to &quot;10.1 Risques&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Risque</th><th>Probabilité</th><th>Impact</th><th>Parade</th></tr></thead><tbody><tr><td>R1</td><td>Homologation NACEF tardive ou exigeant un module matériel</td><td>Moyenne</td><td>Fort (TN restauration)</td><td>Démarrer par le commerce de détail ; partenariat avec un fournisseur homologué ; préinscriptions</td></tr><tr><td>R2</td><td>Facturation en euros impossible ou coûteuse pour les Tunisiens (change, retenue)</td><td>Forte</td><td>Fort</td><td>Distributeur local puis société tunisienne ; grille en DT</td></tr><tr><td>R3</td><td>Guerre des prix (Kesti à 29 DT, offres gratuites en France)</td><td>Forte</td><td>Moyen</td><td>Ne pas descendre sous 39 DT / 29 € ; vendre l&#39;anti-fraude, l&#39;offline, la conformité</td></tr><tr><td>R4</td><td>Coût de la PA qui mange la marge d&#39;Essentiel</td><td>Moyenne</td><td>Moyen</td><td>E-reporting en option sur Essentiel ; négociation volume avant inclusion</td></tr><tr><td>R5</td><td>Nouveau revirement NF525 (certification obligatoire)</td><td>Faible à moyenne</td><td>Fort (FR)</td><td>Lancer le dossier dès le T2 2027 ; versioning strict</td></tr><tr><td>R6</td><td>Fondateur seul : vente, support et produit en même temps</td><td>Forte</td><td>Fort</td><td>Revendeurs et comptables ; support N0 riche ; recruter un commercial terrain en Tunisie au T4</td></tr><tr><td>R7</td><td>Panne ou faille côté serveur au début de la production</td><td>Moyenne</td><td>Fort (réputation)</td><td>La caisse continue hors ligne ; sauvegardes testées ; supervision avant le premier client</td></tr><tr><td>R8</td><td>Pas de référence → méfiance (« pérennité de l&#39;éditeur ? »)</td><td>Forte au départ</td><td>Moyen</td><td>Programme pilote, réversibilité des données (exports CSV, FEC), contrat clair</td></tr><tr><td>R9</td><td>Écarts produit visibles en démo (menu QR, poids, TPE intégré)</td><td>Moyenne</td><td>Moyen</td><td>Phase 4 priorisée par les retours des pilotes ; ne pas démontrer ce qui n&#39;existe pas</td></tr><tr><td>R10</td><td>Contact public sur une adresse personnelle et absence de mentions légales</td><td>Certaine aujourd&#39;hui</td><td>Moyen (crédibilité, conformité)</td><td>Domaine et adresse professionnelle dès la création de la société</td></tr></tbody></table><h3 id="_10-2-decisions-a-prendre-par-ahmed" tabindex="-1">10.2 Décisions à prendre par Ahmed <a class="header-anchor" href="#_10-2-decisions-a-prendre-par-ahmed" aria-label="Permalink to &quot;10.2 Décisions à prendre par Ahmed&quot;">​</a></h3><ol><li><strong>Où créer la société éditrice</strong> (France, Tunisie, ou les deux) et <strong>qui facture en Tunisie</strong> (société locale ou distributeur).</li><li><strong>Valider les grilles</strong> : DT 39 / 69 / 99 (+15) pour la Tunisie ; € 29 / 49 / 79 (+9) avec offre fondateurs pour la France ; essai 30 jours en Tunisie.</li><li><strong>Inclure ou non l&#39;e-reporting</strong> dans Essentiel (dépend du prix négocié avec la PA).</li><li><strong>Homologation NACEF en propre ou via un partenaire homologué</strong> (après lecture du cahier des charges).</li><li><strong>Choix de la PA</strong> (iopole ou B2Brouter) et de l&#39;organisme NF525 (AFNOR / INFOCERT ou LNE).</li><li><strong>Premier recrutement</strong> : commercial terrain en Tunisie ou responsable partenariats en France.</li><li><strong>Liste des 10 pilotes</strong> et conditions (gratuité 3 mois contre témoignage et captures).</li></ol><hr><h2 id="_11-points-non-verifies-au-05-11-2026" tabindex="-1">11. Points non vérifiés (au 05/11/2026) <a class="header-anchor" href="#_11-points-non-verifies-au-05-11-2026" aria-label="Permalink to &quot;11. Points non vérifiés (au 05/11/2026)&quot;">​</a></h2><ul><li>Nombre officiel de commerces de détail et de cafés en Tunisie (INS 2024) ; nombre d&#39;établissements soumis à NACEF ; liste et nombre de fournisseurs homologués (jibaya.tn géo-bloqué).</li><li>Règles de change et retenue à la source pour une société tunisienne qui paie un abonnement à un éditeur étranger ; taux de TVA tunisien applicable aux abonnements logiciels.</li><li>Prix des tablettes, imprimantes et tiroirs chez les revendeurs tunisiens.</li><li>Grilles officielles 2026 de Zettle, Tactill, Hiboutik, Clyo et Lightspeed Retail (seules des sources tierces divergentes ont été trouvées) ; L&#39;Addition ne publie plus qu&#39;un devis.</li><li>Dates 2027 de Franchise Expo Paris, du congrès de l&#39;Ordre des experts-comptables, d&#39;IFSA Africa et d&#39;un salon tunisien de la franchise.</li><li>Date de référence du chiffre de 21 611 experts-comptables (2023 ou 2025).</li><li>Toutes les lignes marquées [Estimation] : mix de formules, conversions, churn, CAC, budgets, objectifs — à recalibrer après les 10 pilotes.</li></ul></div>',1)])])}const g=e(s,[["render",i]]);export{p as __pageData,g as default};
